  "type": "object",
  "properties": {
    "description": {
      "type": "string"
    },
    "loop_type": {
      "type": "string",
      "enum": [
        "task",
        "todo",
        "draft",
        "decision"
      ]
    },
    "priority": {
      "type": "integer",
      "minimum": 1,
      "maximum": 5
